import asyncio
from sc2 import maps, run_game, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.bot_ai import BotAI
from sc2.ids.unit_typeid import UnitTypeId
from sc2.ids.ability_id import AbilityId
from sc2.ids.upgrade_id import UpgradeId
from sc2.position import Point2
from sc2.data import Result

class ZergRushBot(BotAI):
    async def on_start(self):
        await self.client.chat_send("GL HF! Prepare for the Zerg rush!", team_only=False)
        await self.client.game_step(2)
        self.rush_started = False

    async def on_step(self, iteration):
        # Send a chat message at the start of the rush
        if not self.rush_started and self.supply_used >= 14:
            await self.client.chat_send("Zerg rush incoming!", team_only=False)
            self.rush_started = True

        await self.inject_hatcheries()
        await self.manage_resources()
        await self.research_upgrades()
        await self.train_units()
        await self.build_structures()
        await self.attack_enemy()
        await self.draw_creep_pixelmap()

    async def on_end(self, result: Result):
        print(f"Game ended with result: {result}")

    async def inject_hatcheries(self):
        for queen in self.units(UnitTypeId.QUEEN).idle:
            abilities = await self.get_available_abilities(queen)
            for hatch in self.townhalls.ready:
                if AbilityId.EFFECT_INJECTLARVA in abilities and queen.energy >= 25:
                    if queen.distance_to(hatch) < 8:
                        queen(AbilityId.EFFECT_INJECTLARVA, hatch)
                        break

    async def manage_resources(self):
        # Extractor trick for early gas
        if self.supply_used >= 13 and self.already_pending(UnitTypeId.EXTRACTOR) == 0 and self.structures(UnitTypeId.EXTRACTOR).amount < 1:
            for drone in self.workers.idle:
                vgs = self.vespene_geyser.closer_than(10, self.townhalls.first)
                for vg in vgs:
                    if self.can_afford(UnitTypeId.EXTRACTOR):
                        drone.build(UnitTypeId.EXTRACTOR, vg)
                        return

        # Assign drones to gas
        for extractor in self.gas_buildings.ready:
            if extractor.assigned_harvesters < extractor.ideal_harvesters:
                available = self.workers.closer_than(10, extractor)
                if available:
                    self.workers.random.gather(extractor)

        # Keep making drones until 16 on minerals
        if self.supply_workers < 16 and self.can_afford(UnitTypeId.DRONE):
            for hatch in self.townhalls.ready.idle:
                hatch.train(UnitTypeId.DRONE)

    async def research_upgrades(self):
        # Research Zergling speed
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready and self.can_afford(UpgradeId.ZERGLINGMOVEMENTSPEED):
            pool = self.structures(UnitTypeId.SPAWNINGPOOL).ready.first
            abilities = await self.get_available_abilities(pool)
            if AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST in abilities:
                pool(AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST)

    async def train_units(self):
        # Train Zerglings
        for hatch in self.townhalls.ready:
            if self.can_afford(UnitTypeId.ZERGLING) and self.supply_left > 0:
                hatch.train(UnitTypeId.ZERGLING)
        # Train Overlords if supply is low
        if self.supply_left < 2 and self.can_afford(UnitTypeId.OVERLORD):
            for hatch in self.townhalls.ready.idle:
                hatch.train(UnitTypeId.OVERLORD)
        # Train Queens for injects
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready and self.units(UnitTypeId.QUEEN).amount < self.townhalls.ready.amount:
            for hatch in self.townhalls.ready.idle:
                if self.can_afford(UnitTypeId.QUEEN):
                    hatch.train(UnitTypeId.QUEEN)

    async def build_structures(self):
        # Build Spawning Pool at 12 supply
        if self.supply_used >= 12 and not self.structures(UnitTypeId.SPAWNINGPOOL):
            if self.can_afford(UnitTypeId.SPAWNINGPOOL):
                pos = await self.find_placement(UnitTypeId.SPAWNINGPOOL, near=self.townhalls.first.position.towards(self.game_info.map_center, 5))
                if pos:
                    drone = self.workers.random
                    drone.build(UnitTypeId.SPAWNINGPOOL, pos)
        # Build Extractor if not already built (handled in manage_resources)
        # Build additional Hatchery if minerals are floating
        if self.minerals > 400 and self.townhalls.amount < 2:
            pos = await self.get_next_expansion()
            if pos:
                drone = self.workers.closest_to(pos)
                drone.build(UnitTypeId.HATCHERY, pos)

    async def attack_enemy(self):
        # Attack enemy structures with all Zerglings
        if self.units(UnitTypeId.ZERGLING).amount > 10:
            targets = self.enemy_structures
            if not targets:
                targets = self.enemy_start_locations
            for zergling in self.units(UnitTypeId.ZERGLING).idle:
                if targets:
                    target = targets.closest_to(zergling)
                    zergling.attack(target.position if hasattr(target, "position") else target)

    async def draw_creep_pixelmap(self):
        # Draw creep as purple pixels for debugging
        for (x, y), value in np.ndenumerate(self.state.creep.data_numpy):
            if value:
                pos = Point2((x, y))
                await self._client.debug_text_world("•", pos, color=(128, 0, 128), size=8)

import numpy as np

def main():
    run_game(
        maps.get("AcropolisLE"),
        [
            Bot(Race.Zerg, ZergRushBot()),
            Computer(Race.Terran, Difficulty.Medium)
        ],
        realtime=False,
        save_replay_as="zerg_rush_bot.SC2Replay"
    )

if __name__ == "__main__":
    main()
